/*
 * 【解题思路】合并两个有序数组（优化解）
 * 为什么这样做：把A末尾的空位当作输出位置。两个数组的最大值放到A最末尾，谁大谁后移指针，这样覆盖不会破坏未处理数据。
 * 关键理解：i=m−1只指向A的有效元素，不能把预留空位当成数据。
 * 关键理解：k从最右端开始写，使尚未处理的A前段始终安全。
 * 关键理解：只需while(j>=0)，因为B耗尽后A剩余元素已经在正确位置。
 * 考场注意：满足最小额外空间要求，考场优先掌握。
 */
#include <stdio.h>

// 从右到左：永远把两段未处理数据中的最大值写到A末尾
void merge(int A[], int m, int B[], int n) {
    int i = m-1;             // A最后一个有效元素
    int j = n-1;             // B最后一个元素
    int k = m+n-1;           // A最后一个容量位置
    while (j >= 0) {         // B全部放进A就完成；A剩下的不需动
        // 先确认 A 仍有有效元素，再将较大值放到末尾；从后向前写不会覆盖未处理数据。
        if (i >= 0 && A[i] > B[j])
            A[k--] = A[i--]; // A较大，把A的值放到最终末尾
        else
            A[k--] = B[j--]; // B较大或A已耗尽
    }
}
int main(void) {
    int A[6] = {1,3,5,0,0,0}, B[3] = {2,4,6};
    merge(A,3,B,3);
    for (int i=0;i<6;i++) printf("%d%c",A[i],i==5?'\n':' ');
    return 0;
}

