/*
 * 【解题思路】寻找单链表的中间结点（优化解）
 * 为什么这样做：fast每轮走2步，slow每轮走1步。当fast到链尾时slow恰好到中间位置。
 * 关键理解：while同时检查fast和fast->next，才能安全访问fast->next->next。
 * 关键理解：每次慢指针只走一格，快指针走两格。
 * 关键理解：遇到偶数结点时fast为NULL，slow恰好停在第二中点。
 * 考场注意：没有降低数量级，但减少一次完整遍历；适合练习快慢指针。
 */
#include <stdio.h>
typedef struct Node { int data; struct Node *next; } Node;
Node* middle(Node *head) {
    Node *slow=head,*fast=head; // 两者同时从首结点出发
    while(fast!=NULL && fast->next!=NULL) {
        slow=slow->next;          // 慢指针每轮一步
        fast=fast->next->next;    // 快指针每轮两步
    }
    return slow; // 偶数长度时指向靠后的中间结点
}
int main(void){
    Node f={6,NULL},e={5,&f},d={4,&e};
    Node c={3,&d},b={2,&c},a={1,&b};
    Node *p=middle(&a);
    if(p) printf("%d\n",p->data);
    return 0;
}

