/*
 * 【解题思路】求二叉树最大深度（朴素解）
 * 为什么这样做：空树深度为0。非空树的深度等于左右子树深度较大值+1。
 * 关键理解：root==NULL是递归出口，否则会一直访问空指针。
 * 关键理解：左右子树的最大深度是两个独立子问题。
 * 关键理解：根本身占一层，所以结果是max(left,right)+1。
 * 考场注意：已达到线性时间，代码短且考场性价比很高，是本题首选。
 */
#include <stdio.h>
typedef struct Node{
    int data;
    struct Node *left,*right; // 二叉树的左右孩子
}Node;
int depth(Node *root){
    if(root==NULL)return 0;  // 空树高度为0，递归出口
    int a=depth(root->left); // 求左子树高度
    int b=depth(root->right);// 求右子树高度
    return (a>b?a:b)+1;      // 取更高子树并加上根所在一层
}
int main(void){
    Node d={4,NULL,NULL},b={2,&d,NULL},c={3,NULL,NULL};
    Node a={1,&b,&c};
    printf("%d\n",depth(&a));
    return 0;
}

