/*
 * 【解题思路】求二叉树最大深度（优化解）
 * 为什么这样做：二叉树逐层入队；每处理完整一层，深度加1。它与递归同为O(n)时间，不必因为迭代就认为更优。
 * 关键理解：front和rear分别表示队头下标和队尾后一个位置。
 * 关键理解：cnt在这一层开始时就固定，避免把新入队的下一层结点混入本轮。
 * 关键理解：每完整处理一层再加1，直到队列为空。
 * 考场注意：适合考层序遍历，但本题递归法通常更简单，优化不意味着数量级更优。
 */
#include <stdio.h>
#define MAXN 100
typedef struct Node{
    int data;
    struct Node *left,*right;
}Node;
int depth(Node *root){
    if(!root)return 0;
    Node *Q[MAXN];               // 顺序队列存储当前层及下一层结点
    int front=0,rear=0,h=0;
    Q[rear++]=root;              // 根结点先入队
    while(front<rear){
        int cnt=rear-front;      // 本轮开始时这一层的结点数
        for(int i=0;i<cnt;i++){
            Node *p=Q[front++];  // 逐个取出本层结点
            if(p->left)Q[rear++]=p->left;
            if(p->right)Q[rear++]=p->right;
        }
        h++;                      // 本层处理完，树高加一
    }
    return h;                    // 假定整棵树结点总数不超过MAXN
}
int main(void){
    Node d={4,NULL,NULL},b={2,&d,NULL},c={3,NULL,NULL};
    Node a={1,&b,&c};
    printf("%d\n",depth(&a));
    return 0;
}

