/*
 * 【解题思路】在有序数组中寻找目标值（优化解）
 * 为什么这样做：左右边界l、r维护可能存在目标的闭区间。比较中点，小了丢掉左半段，大了丢掉右半段。
 * 关键理解：闭区间初始化为[0,n−1]，所以使用l<=r。
 * 关键理解：mid确定后若不相等，就排除mid本身，用mid+1或mid−1。
 * 关键理解：每轮候选区间约缩小一半，所以O(log n)。
 * 考场注意：408重点算法，写清楚区间边界就很可靠，考场推荐。
 */
#include <stdio.h>
// 采用闭区间[l,r]，循环条件是l<=r
int search(int a[],int n,int target){
    int l=0,r=n-1;
    // 闭区间两端均可能包含目标，因此相等时仍须检查最后一个候选位置。
    while(l<=r){
        int mid=l+(r-l)/2;        // 求中点，避免l+r过大
        if(a[mid]==target)return mid;
        if(a[mid]<target)l=mid+1;// 左半部分都太小，直接丢弃
        else r=mid-1;            // 右半部分都太大，直接丢弃
    }
    return -1;                    // 区间变空说明目标不存在
}
int main(void){
    int a[]={1,3,5,7,9,11};
    printf("%d\n",search(a,6,7));
    return 0;
}

