/*
 * 【解题思路】判断无向图是否连通（朴素解）
 * 为什么这样做：从0出发遇到未访问的邻接点就递归访问，最后统计visited中是否全部为1。
 * 关键理解：visited必须先标记，再继续递归，否则环路会导致反复访问。
 * 关键理解：邻接矩阵每次访问顶点u时需扫描它所在的一整行。
 * 关键理解：连通无向图从0出发应能到达所有顶点。
 * 考场注意：考纲经典，适合考场写。对于邻接矩阵，BFS在渐近时间上并不更优。
 */
#include <stdio.h>
#define N 5
void dfs(int u,int g[N][N],int vis[]){
    vis[u]=1;                             // 标记当前顶点已访问
    for(int v=0;v<N;v++){
        if(g[u][v] && !vis[v])dfs(v,g,vis); // 发现邻接且未访问就递归
    }
}
int connected(int g[N][N]){
    int vis[N]={0};
    dfs(0,g,vis);                         // 只从顶点0开始搜索
    for(int i=0;i<N;i++)if(!vis[i])return 0; // 存在未访问点即不连通
    return 1;
}
