/*
 * 【解题思路】判断无向图是否连通（优化解）
 * 为什么这样做：从顶点0入队，弹出一个顶点就检查其所有邻接点，把没访问过的加入队列。最终统计访问总数。
 * 关键理解：BFS用先进先出的队列维护待访问的顶点。
 * 关键理解：入队时标记visited，保证每个顶点最多入队一次。
 * 关键理解：若count小于N，则至少有一个顶点与0不连通。
 * 考场注意：与DFS复杂度相同，是必须掌握的另一种遍历，不必强行认为它更省时间。
 */
#include <stdio.h>
#define N 5
int connected(int g[N][N]){
    int q[N],front=0,rear=0,vis[N]={0},count=0;
    q[rear++]=0;vis[0]=1;                // 入队时立刻标记，避免重复入队
    while(front<rear){
        int u=q[front++];count++;       // 出队并计数
        for(int v=0;v<N;v++){
            if(g[u][v] && !vis[v]){
                vis[v]=1;
                q[rear++]=v;            // 只有未访问的邻接点才入队
            }
        }
    }
    return count==N;                    // n个顶点都能到达则连通
}
int main(void){
    int g[N][N]={0};
    int e[][2]={{0,1},{0,2},{1,3},{2,4}};
    for(int i=0;i<4;i++){int u=e[i][0],v=e[i][1];g[u][v]=g[v][u]=1;}
    printf("%d\n",connected(g));
    return 0;
}

