/*
 * 【解题思路】用两个栈模拟先进先出的队列（优化解）
 * 为什么这样做：新元素全部压入in栈。需要取队首而out栈为空时，把in中的元素逐个弹出压入out，这样原本最早入队的元素来到out栈顶。
 * 关键理解：in栈负责接收新元素，out栈负责把最早入队者送到栈顶。
 * 关键理解：只有out为空才把in全部倒入，否则顺序会错误。
 * 关键理解：每个元素最多进出两个栈各一次，因此单次出队的均摊复杂度O(1)。
 * 考场注意：原题限定‘只用两个栈’时应写这种方法；记住只有out为空才倒入元素。
 */
#include <stdio.h>
#define CAP 100
typedef struct{
    int in[CAP],out[CAP];
    int ni,no;                          // 两个栈当前元素数
}Queue;
void push(Queue*q,int x){
    if(q->ni+q->no<CAP)q->in[q->ni++]=x; // 新元素先压入in
}
void refill(Queue*q){
    if(q->no==0){                     // out不空时不能重新倒入
        while(q->ni>0)
            q->out[q->no++]=q->in[--q->ni]; // 倒序后旧元素在栈顶
    }
}
int pop(Queue*q){
    refill(q);
    return q->no? q->out[--q->no]:-1; // 弹出out栈顶
}
int peek(Queue*q){
    refill(q);
    return q->no? q->out[q->no-1]:-1;
}
int main(void){
    Queue q={{0},{0},0,0};
    push(&q,1);push(&q,2);
    int a=pop(&q);int b=peek(&q);
    printf("%d %d\n",a,b);
    return 0;
}

