#include <stdio.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

// 朴素解法：额外用数组保存结点地址，再倒序重连。
Node *reverseWithArray(Node *head, Node *refs[]) {
    int n = 0;
    for (Node *p = head; p != NULL; p = p->next) {
        refs[n++] = p;
    }

    for (int i = n - 1; i > 0; i--) {
        refs[i]->next = refs[i - 1];
    }
    if (n > 0) {
        refs[0]->next = NULL;
        return refs[n - 1];
    }
    return NULL;
}

