/*
 * 【解题思路】单链表原地逆置（优化解）
 * 为什么这样做：三指针prev、cur、next逐条改变链表指向
 * 关键理解：prev 表示逆置后链表的头，cur 表示待处理结点。
 * 关键理解：先保存 next，再让 cur->next 指向 prev；随后移动 prev 和 cur。
 * 关键理解：空链表直接返回 NULL，单结点链表原样返回；全程仅用三个指针。
 * 考场注意：务必先用 next 保存 cur->next，再修改 cur->next；否则剩余链表会丢失。
 */
#include <stdio.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

// 三指针原地逆置：O(n) 时间，O(1) 额外空间。
Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;

    while (cur != NULL) {
        Node *next = cur->next;  // 先保留后继，避免断链
        cur->next = prev;        // 当前结点指向前驱
        prev = cur;              // 前驱前进
        cur = next;              // 处理原链表下一个结点
    }
    return prev;  // 新表头
}

int main(void) {
    Node a[4];
    for (int i = 0; i < 4; i++) {
        a[i].data = i + 1;
        a[i].next = (i < 3) ? &a[i + 1] : NULL;
    }

    Node *head = reverse(&a[0]);
    for (Node *p = head; p != NULL; p = p->next) {
        printf("%d%c", p->data, p->next ? ' ' : '\n');
    }
    return 0;
}

