/*
 * 【解题思路】二叉树最近公共祖先（优化解）
 * 为什么这样做：空结点返回-1；遇到p或q返回自身；左右递归若均非空，则当前结点就是答案；否则返回非空一侧。
 * 关键理解：遇到空结点或目标结点直接返回
 * 关键理解：分别获取左右子树的搜索结果
 * 关键理解：两侧都找到则当前结点为LCA，否则向上返回非空结果
 * 考场注意：必须保证两目标都存在；若不保证，需要另行验证。
 */
#include <stdio.h>

#define N 5

// 用数组存储二叉树：-1 表示没有孩子
typedef struct {
    int data, left, right;
} Node;

Node tree[N] = {
    {3, 1, 2}, {5, 3, 4}, {1, -1, -1},
    {6, -1, -1}, {2, -1, -1}
};

// 后序思想：左右子树各返回找到的目标结点
int lca(int u, int p, int q) {
    if (u == -1 || u == p || u == q)
        return u;

    int left = lca(tree[u].left, p, q);
    int right = lca(tree[u].right, p, q);

    // 左右子树各返回一个有效结点，说明两个目标分处两侧，首次汇合点就是 u。


    // 如果某一侧已经求出更低的公共祖先，另一侧不可能再有另一个目标（假设目标结点唯一）。


    if (left != -1 && right != -1)
        return u; // 两边各有一个目标，当前结点是最近公共祖先

    // 两边均有结果时已在上方返回当前结点；执行到这里说明至多一边有结果。


    // 若仅左边有结果，原样上传左边找到的目标或已确定的最近公共祖先；否则上传右边结果。


    // 若左右都为 -1，右边也是 -1，返回 -1 表示整棵当前子树都没有找到目标。


    // 不能无条件返回 u：u 虽可能是公共祖先，但不一定是“最近”的。


    return left != -1 ? left : right;
}

int main(void) {
    int p = 3, q = 4; // 6 与 2
    int ans = lca(0, p, q);
    printf("%d\n", tree[ans].data); // 5
    return 0;
}

