/*
 * 【解题思路】相交链表：找到公共尾链的起点（优化解）
 * 为什么这样做：p、q 分别从 A、B 出发；走到 NULL 后切换到另一条链表的头部。两者各走 m+n 步后长度差抵消，最终在交点或 NULL 相遇。
 * 关键理解：p 指向 A 头，q 指向 B 头。
 * 关键理解：每次各走一步，走完后换到另一条链表。
 * 关键理解：p == q 时停止；相交返回地址，否则返回 NULL。
 * 考场注意：切换条件是 p == NULL，不是 p->next == NULL；无交点时两者会同时变成 NULL。
 */
#include <stdio.h>

// 两条链表共享同一段尾链：8 -> 10
typedef struct Node {
    int data;
    struct Node *next;
} Node;

Node end = {10, NULL};
Node shared = {8, &end};
Node a2 = {4, &shared};
Node a1 = {1, &a2};
Node b3 = {5, &shared};
Node b2 = {6, &b3};
Node b1 = {2, &b2};

// 双指针：各自走完一条链后切换到另一条链
Node *intersection(Node *a, Node *b) {
    Node *p = a, *q = b;
    while (p != q) {
        p = (p == NULL) ? b : p->next;
        q = (q == NULL) ? a : q->next;
    }
    return p; // 相交则返回公共结点，否则均为 NULL
}

int main(void) {
    Node *ans = intersection(&a1, &b1);
    // 本例输出 8；无交点则输出 -1
    printf("%d\n", ans ? ans->data : -1);
    return 0;
}

